blocks.text:
 * "body" (instead of "reply", as inline text) — the AI agent frequently mirrors
 * field names from input/<TICKET>/pr_discussions_raw.json (rootCommentId/body)
 * rather than renaming them to the documented output schema.
 *
 * Id enrichment (gh-692): a missing threadId/inReplyToId is filled in from the
 * setup-time snapshot input/<ticketKey>/pr_discussions_raw.json (matched by the
 * id that IS present), so a reply becomes threaded and its thread resolvable
 * even when the agent dropped one of the two ids.
 *
 * Closure sweep (gh-692): after the per-item pass, resolveRemainingAddressedThreads()
 * resolves every still-open thread the rework addressed — including threads whose
 * ids only appear in the rework response text (outputOptions.responseText). Without
 * this step the threadsResolved:true re-review rule can never match.
 *
 * Anti-spam: replies without any usable comment id (no inReplyToId/rootCommentId,
 * even after enrichment) cannot be posted as an inline threaded reply. Instead of
 * posting one generic top-level PR comment per such item (which spams the
 * conversation with repeated "✅ Addressed." messages), all of them are batched
 * into a single combined top-level comment — the specified fallback for
 * unciteable items.
 */
function postThreadReplies(scm, pullRequestId, outputOptions) {
    outputOptions = outputOptions || {};
    var lookup = buildThreadLookup(readInputRawThreads(outputOptions.ticketKey, outputOptions));

    // gh-799: shared reader — the completion live-state reads the same file the
    // same way, so coverage accounting and reply posting can never drift apart.
    var repliesFile = readRepliesArray(outputOptions);
    if (repliesFile.missing) {
        console.warn('outputs/review_replies.json not found — skipping thread replies');
    }

    const replies = repliesFile.replies;
    if (replies.length === 0) {
        console.log('No thread replies to post');
    }

    let posted = 0;
    const untargeted = [];
    const addressed = { threadIds: {}, rootIds: {} };
    // gh-957: lap-accounting counter — incremented on every successful
    // resolution so the leg close can stamp an accurate lap marker.
    const resolutions = outputOptions.resolutions || null;
    const state = { posted: 0, untargeted: untargeted, resolutions: resolutions };
    // gh-957 audit-resolve: when the leg changed no code, every reply below
    // carries the audit line (rework run URL) — resolution without a code
    // change is allowed ONLY with this per-thread explanation.
    const auditLine = buildAuditResolveLine(outputOptions.auditNoCodeChange, outputOptions.runUrl);

    replies.forEach(function(item) {
        // Accept both the documented field names (inReplyToId/reply) and the
        // input-schema field names (rootCommentId/body) — the AI agent commonly
        // mirrors field names from input/<TICKET>/pr_discussions_raw.json
        // instead of renaming them for output. gh-692 fills either missing id
        // from the setup-time snapshot so the reply is threaded + resolvable.
        const inReplyToId = enrichReplyIds(item, lookup);
        const replyText = resolveReplyText(item.reply || item.body, outputOptions) + (auditLine || '');
        const thread = { rootCommentId: inReplyToId, threadId: item.threadId || null };

        // Track every id this rework claims as addressed — the closure sweep
        // below retries resolution for anything the per-item pass could not
        // name or complete.
        if (item.threadId) addressed.threadIds[String(item.threadId)] = true;
        if (inReplyToId) addressed.rootIds[String(inReplyToId)] = true;

        postReplyAndResolve(scm, pullRequestId, item, thread, replyText, state);
    });
    posted = state.posted;

    if (untargeted.length > 0) {
        // Post exactly one combined top-level comment for all untargeted replies
        // instead of one generic comment per item.
        try {
            scm.addComment(pullRequestId, buildCombinedUntargetedComment(untargeted));
            console.log('✅ Posted 1 combined comment for ' + untargeted.length + ' untargeted repl' + (untargeted.length === 1 ? 'y' : 'ies'));
            posted++;
        } catch (e) {
            console.warn('Failed to post combined untargeted reply comment:', e.message || e);
        }
    }

    // Closure step (gh-692): sweep the PR's fresh open threads and resolve every
    // still-open thread this rework addressed — plus the ids cited in the rework
    // response, which MUST be resolved. Runs even when review_replies.json was
    // missing entirely.
    resolveRemainingAddressedThreads(scm, pullRequestId, {
        citedThreadIds: extractCitedThreadIds(outputOptions.responseText),
        addressedThreadIds: addressed.threadIds,
        addressedRootIds: addressed.rootIds,
        resolutions: outputOptions.resolutions || null
    });

    console.log('Posted ' + posted + '/' + replies.length + ' thread replies');
    return posted;
}

function postPRComment(scm, pullRequestId, fixSummary, ticketKey, repliesPosted) {
    try {
        var commentText;
        if (repliesPosted > 0) {
            // When review thread replies exist, keep the top-level comment minimal.
            // The detailed answers live in the thread replies.
            commentText = '## 🔧 Rework Complete — ' + ticketKey + '\n\n' +
                'All review feedback has been addressed in the thread replies above.';
        } else {
            commentText = '## 🔧 Rework Complete — ' + ticketKey + '\n\n' +
                'All PR review comments have been addressed. See fix summary below.\n\n' +
                '---\n\n' +
                fixSummary;
        }
        scm.addComment(pullRequestId, commentText);
        console.log('✅ Posted fix summary to PR #' + pullRequestId);
        return true;
    } catch (error) {
        console.error('Failed to post PR comment:', error);
        return false;
    }
}

/**
 * gh-799: posts the completion comment generated from the LIVE PR state
 * (buildCompletionLiveState — live unresolved-thread re-check + verdict probe
 * + reply coverage). liveState may be null for legacy callers — that maps to
 * the clean path, preserving the historical wording.
 */
function postJiraComment(tracker, ticketKey, prUrl, branchName, prCommentPosted, codeChangesCommitted, fixSummary, liveState) {
    try {
        const m = commentMarkup.forTicket(ticketKey);
        const live = liveState || {};
        const comment = buildReworkCompletionComment(m, {
            ticketKey: ticketKey,
            prUrl: prUrl,
            branchName: branchName,
            prCommentPosted: prCommentPosted,
            codeChangesCommitted: codeChangesCommitted,
            liveOpenThreads: live.liveOpenThreads || [],
            inputThreads: live.inputThreads || [],
            unaddressed: live.unaddressed || [],
            verdict: live.verdict || null
        });

        tracker.postComment(ticketKey, comment);
        console.log('✅ Posted completion comment to ticket:', ticketKey);
    } catch (error) {
        console.error('Failed to post tracker comment:', error);
    }
}

function isInterruptedReworkResponse(response) {
    var text = String(response || '');
    return text.indexOf('CLI command executed but did not produce output file') !== -1 ||
        text.indexOf('Command failed (exit code 124)') !== -1 ||
        text.indexOf('Copilot command timed out') !== -1 ||
        text.indexOf('outputs/response.md missing') !== -1 ||
        text.indexOf('"path":"interrupted"') !== -1 ||
        text.indexOf('"path": "interrupted"') !== -1;
}

/**
 * Fatal (non-interruption) CLI failure in the rework response.
 *
 * Live pathology 2026-09-29 (IstiN/flutter_agent_harness #1052 machine loop):
 * a rework CLI command that exited non-zero (exit code 1) was announced as
 * "✅ Rework Complete" because only interruption-class failures (timeout exit
 * 124, missing output file) were detected. The loop then re-validated a head
 * that could never go green — forever.
 *
 * The `Error: Command failed (exit code N)` marker is written by the
 * CliExecutionHelper into the RAW c…

/**
 * SCM-agnostic git operations for PR setup actions.
 *
 * Unlike js/common/githubHelpers.js (which wraps GitHub-only REST/GraphQL
 * calls — PR conversations, check-runs, job logs), everything in this module
 * is plain `git` CLI plumbing invoked via `cli_execute_command`. It works
 * identically for GitHub- and GitLab-backed repositories, since neither the
 * branch checkout nor the diff/conflict/context logic ever calls a
 * provider-specific tool.
 *
 * Used by preCliReworkSetup.js, preCliTestReworkSetup.js,
 * preparePRForReview.js, prepareTestPRForReview.js (regardless of
 * config.scm.provider).
 *
 * Writes the following files to input/{ticketKey}/ (via writePRContext):
 *   pr_info.md            — PR metadata
 *   pr_diff.txt           — git diff context, truncated when large
 *   pr_discussions.md     — human-readable review threads + comments
 *   pr_discussions_raw.json — structured threads with IDs for reply/resolve
 */

const { GIT_CONFIG } = require('../config.js');
const prHelper = require('./pullRequest.js');
var gitStaging = require('./gitStaging.js');

var MAX_PR_DIFF_CONTEXT_CHARS = 12000;

// Canonical copy (gh-823/gh-912): the warning:/note: line filter lives in
// common/pullRequest.js once — this delegate keeps every local call site.
function cleanCommandOutput(output) {
    return prHelper.cleanCommandOutput(output);
}

/**
 * Switches the working tree onto `branchName` (creating a local tracking
 * branch from origin when needed). Assumes the working tree is already clean —
 * callers (checkoutPRBranch) are responsible for stashing local state first.
 */
function _switchToBranch(branchName, cmd) {
    var localBranchExists = function() {
        return cleanCommandOutput(cmd('git branch --list "' + branchName + '"') || '').trim() !== '';
    };

    // Targeted fetch of just this branch (owner rule 2026-10-03: blanket
    // `fetch origin --prune` cost 134s on big repos; the base branch is
    // fetched explicitly by ensureRemoteBranchRef in checkoutPRBranch).
    // Forced remote-tracking refspec (+refs/heads/<b>:refs/remotes/origin/<b>)
    // — a plain '<branch>:<branch>' refspec would try to update the local
    // branch ref and fails when HEAD is on that branch.
    var targetedFetch = prHelper.buildTargetedOriginFetchCommand([branchName]);
    if (targetedFetch) cmd(targetedFetch);

    if (localBranchExists()) {
        cmd('git checkout ' + branchName);
        // Use reset --hard instead of pull: after a force-push (e.g. a rebase),
        // local and remote branches diverge and 'git pull' fails with
        // "Need to specify how to reconcile divergent branches".
        // The remote is always the source of truth for an existing PR branch.
        cmd('git reset --hard origin/' + branchName);
    } else {
        // gh-912: decide on a real refs/heads/<branch> ref line — a
        // warning-only capture (central-mode insteadOf origin, git ≥ 2.54)
        // must classify as "branch absent" so the caller gets the explicit
        // not-found decision instead of a fatal mid-fetch/mid-checkout.
        var remoteBranchExists = prHelper.remoteBranchExists(cmd, null, branchName);
        if (remoteBranchExists) {
            try {
                cmd(prHelper.buildOriginFetchCommand(branchName + ':' + branchName));
            } catch (e) {
                cmd(prHelper.buildOriginFetchCommand(branchName));
            }

            if (localBranchExists()) {
                cmd('git checkout ' + branchName);
            } else {
                try {
                    cmd('git checkout -b ' + branchName + ' origin/' + branchName);
                } catch (e) {
                    if (!localBranchExists()) {
                        throw e;
                    }
                    cmd('git checkout ' + branchName);
                }
            }
        } else {
            throw new Error('Branch not found locally or remotely: ' + branchName);
        }
    }
}

/**
 * Checks out `branchName`, self-healing around a dirty/untracked working tree
 * instead of ever failing the whole setup step or leaving HEAD parked on
 * `baseBranch` (the failure mode that causes WIP auto-save commits to land on
 * develop/main instead of the ticket branch).
 *
 * Strategy ("stage, switch, reapply"):
 *   1. Snapshot any local changes (tracked + untracked) via `git stash -u` so
 *      the tree is guaranteed clean before switching branches.
 *   2. Switch onto `branchName` (create local tracking branch from origin if
 *      needed).
 *   3. Reapply the snapshot on top of the new branch. If it doesn't apply
 *      cleanly, we do NOT fail — the conflict markers are left in the working
 *      tree for the CLI agent (or a human) to resolve as part of its task;
 *      `hadConflict: true` is returned so callers can surface this.
 *   4. Hard invariant: if, after all of this, HEAD still equals `baseBranch`,
 *      recreate `branchName` from `origin/baseBranch` rather than ever
 *      returning while sitting on the base branch.
 *
 * @param {string} branchName
 * @param {string} [workingDir]
 * @param {string} [baseBranch] - when provided, enforces the "never stay on
 *        baseBranch" invariant (step 4). Omit only for call sites that don't
 *        know the base branch; the stash-based self-healing (steps 1-3) still
 *        applies either way.
 * @returns {{ branch: string, hadConflict: boolean }}
 */
function checkoutPRBranch(branchName, workingDir, baseBranch) {
    console.log('Checking out PR branch:', branchName);
    var cmdOpts = workingDir ? { workingDirectory: workingDir } : {};
    var cmd = function(command) { return cli_execute_command(Object.assign({}, cmdOpts, { command: command })); };

    cmd('git config user.name "' + GIT_CONFIG.AUTHOR_NAME + '"');
    cmd('git config user.email "' + GIT_CONFIG.AUTHOR_EMAIL + '"');

    // 1. Snapshot local state so a dirty tree can never block the switch below.
    // factory-kit excluded: the factory workflow's nested machine-infra repo
    // (git init inside the workspace) is a gitlink `git add -A` cannot stage
    // (exit 128, live gh-1000 timer auto-commits failing all session long).
    var dirty = cleanCommandOutput(cmd('git status --porcelain') || '')
        .split('\n')
        .filter(function (line) { return line.trim() && !/^(\?\?|A )\s+factory-kit(\/|$)/.test(line); })
        .join('\n').trim();
    var stashed = false;
    if (dirty) {
        console.log('Working tree has local changes — stashing before branch switch');
        // gh-1164: probe-filtered — a static `:!factory-kit` exclusion trips
        // git add's ignored-pathspec guard when the kit exists AND is
        // gitignored; when it is NOT ignored (the nested-gitlink case) the
        // exclusion is kept and the guard cannot fire.
        cmd('git add -A -- ' + gitStaging.buildExclusionPathspecs(['factory-kit'], function (args) {
            return cmd(args.command);
        }));
        try {
            cmd('git stash push -u -m "preflight-checkout-' + branchName + '"');
            stashed = true;
        } catch (e) {
            console.warn('git stash push failed, proceeding without a safety snapshot:', e);
        }
    }

    // 2. Switch branches — tree is clean now, so this should never fail on
    //    "untracked files would be overwritten" again.
    _switchToBranch(branchName, cmd);

    // 3. Reapply the snapshot on top of the target branch.
    var hadConflict = false;
    if (stashed) {
        try {
            cmd('git stash pop');
        } catch (popErr) {
            hadConflict = true;
            console.warn('⚠️ Reapplying local snapshot onto ' + branchName + ' produced conflicts — leaving conflict markers in place:', popErr);
        }
    }

    // 4. Hard invariant: never report success while parked on the base branch.
    if (baseBranch) {
        // Make sure origin/<baseBranch> tracking ref exists before anything
        // downstream (detectMergeConflicts, getPRDiff, syncBranchWithBase)
        // relies on it — a plain `fetch --prune` above only refreshes refs
        // already tracked per the remote's configured refspec, which is
     …

/**
 * Provider-agnostic AI chat helper for JavaScript actions.
 *
 * DMTools exposes every AI provider's chat tool as a separate global:
 *   gemini_ai_chat, openai_ai_chat, anthropic_ai_chat, ollama_ai_chat,
 *   dial_ai_chat, bedrock_ai_chat, etc.
 *
 * This module picks the first one that is actually available at runtime,
 * so agent JS never hardcodes a specific provider.
 */

var PROVIDERS = [
    'gemini',
    'openai',
    'anthropic',
    'ollama',
    'dial',
    'bedrock'
];

function _tryCall(fnName, message) {
    try {
        var fn = typeof globalThis !== 'undefined' ? globalThis[fnName] : undefined;
        if (!fn && typeof window !== 'undefined') fn = window[fnName];
        if (typeof fn === 'function') {
            return fn(message);
        }
    } catch (e) {
        // Provider present but call failed — re-throw so caller can fall back
        throw e;
    }
    return undefined;
}

/**
 * Send a text message to the configured AI and return the response.
 * Tries providers in order until one succeeds.
 *
 * @param {string} message  — prompt text
 * @returns {string}        — AI response
 * @throws {Error}          — if no AI provider is available or all fail
 */
function aiChat(message) {
    if (!message || typeof message !== 'string') {
        throw new Error('aiChat: message must be a non-empty string');
    }

    var lastError = null;
    for (var i = 0; i < PROVIDERS.length; i++) {
        var fnName = PROVIDERS[i] + '_ai_chat';
        try {
            var result = _tryCall(fnName, message);
            if (result !== undefined) {
                return result;
            }
        } catch (e) {
            lastError = e;
            console.warn('aiChat: ' + fnName + ' failed — trying next provider', e.message || e);
        }
    }

    if (lastError) {
        throw new Error('aiChat: no AI provider succeeded. Last error: ' + (lastError.message || lastError));
    }
    throw new Error('aiChat: no AI provider available (tried ' + PROVIDERS.join(', ') + ')');
}

module.exports = { aiChat: aiChat };

