{"content":"/**
 * Unit tests for js/common/aiChat.js — provider-dispatch chat helper.
 *
 * The module resolves AI provider tools from the global scope
 * (globalThis/window) and tries them in priority order. These tests pin the
 * dispatch order, the validation guard, the last-error propagation and the
 * "no provider" failure shape by injecting provider functions onto the real
 * globalThis (the module reads them at call time).
 *
 * Uses: loadModule(), assert, test(), suite()
 */

var aiChatModule = loadModule('js/common/aiChat.js');

var PROVIDER_NAMES = ['claude_ai_chat', 'gemini_ai_chat', 'codex_ai', 'gemini_cli', 'opencode_ai'];

function clearProviders() {
    PROVIDER_NAMES.forEach(function(name) {
        try { delete globalThis[name]; } catch (e) { globalThis[name] = undefined; }
    });
}

function setProvider(name, fn) {
    globalThis[name] = fn;
}

function getProvider(name) {
    return globalThis[name];
}

suite('aiChat.aiChat', function() {
    test('rejects a missing or non-string message', function() {
        assert.throws(function() { aiChatModule.aiChat(null); }, 'null message must throw');
        assert.throws(function() { aiChatModule.aiChat(42); }, 'numeric message must throw');
        assert.throws(function() { aiChatModule.aiChat({}); }, 'object message must throw');
    });

    test('rejects an empty or whitespace-only message', function() {
        assert.throws(function() { aiChatModule.aiChat(''); }, 'empty message must throw');
        assert.throws(function() { aiChatModule.aiChat('   '); }, 'whitespace-only message must throw');
    });

    test('uses the first available provider and returns its result', function() {
        clearProviders();
        var calls = [];
        setProvider('gemini_ai_chat', function(message) { calls.push(['gemini_ai_chat', message]); return 'gemini-result'; });
        setProvider('codex_ai', function(message) { calls.push(['codex_ai', message]); return 'codex-result'; });

        var result = aiChatModule.aiChat('hello');

        assert.equal(result, 'gemini-result');
        assert.deepEqual(calls, [['gemini_ai_chat', 'hello']], 'higher-priority provider wins, later providers are not tried');
        clearProviders();
    });

    test('claude_ai_chat has priority over gemini_ai_chat', function() {
        clearProviders();
        var calls = [];
        setProvider('claude_ai_chat', function(message) { calls.push('claude_ai_chat'); return 'claude-result'; });
        setProvider('gemini_ai_chat', function(message) { calls.push('gemini_ai_chat'); return 'gemini-result'; });

        var result = aiChatModule.aiChat('hi');

        assert.equal(result, 'claude-result');
        assert.deepEqual(calls, ['claude_ai_chat']);
        clearProviders();
    });

    test('falls through to the next provider when an earlier one is absent', function() {
        clearProviders();
        var calls = [];
        setProvider('opencode_ai', function(message) { calls.push('opencode_ai'); return 'opencode-result'; });

        var result = aiChatModule.aiChat('hi');

        assert.equal(result, 'opencode-result');
        assert.deepEqual(calls, ['opencode_ai'], 'only the present provider is invoked');
        clearProviders();
    });

    test('falls through when a provider throws and surfaces the next provider result', function() {
        clearProviders();
        var calls = [];
        setProvider('gemini_ai_chat', function(message) { calls.push('gemini_ai_chat'); throw new Error('gemini boom'); });
        setProvider('codex_ai', function(message) { calls.push('codex_ai'); return 'codex-result'; });

        var result = aiChatModule.aiChat('hi');

        assert.equal(result, 'codex-result');
        assert.deepEqual(calls, ['gemini_ai_chat', 'codex_ai'], 'a throwing provider is skipped, the next one is tried');
        clearProviders();
    });

    test('falls through when a provider resolves undefined', function() {
        clearProviders();
        var calls = [];
        setProvider('gemini_ai_chat', function(message) { calls.push('gemini_ai_chat'); return undefined; });
        setProvider('gemini_cli', function(message) { calls.push('gemini_cli'); return 'cli-result'; });

        var result = aiChatModule.aiChat('hi');

        assert.equal(result, 'cli-result');
        assert.deepEqual(calls, ['gemini_ai_chat', 'gemini_cli']);
        clearProviders();
    });

    test('throws the last provider error when every provider fails', function() {
        clearProviders();
        setProvider('gemini_ai_chat', function(message) { throw new Error('gemini boom'); });
        setProvider('codex_ai', function(message) { throw new Error('codex kaput'); });

        var caught = null;
        try {
            aiChatModule.aiChat('hi');
        } catch (e) {
            caught = e;
        }

        assert.ok(caught, 'must throw when all providers fail');
        assert.equal(caught.message, 'codex kaput', 'the LAST provider error is propagated');
        clearProviders();
    });

    test('throws the "no provider tools" error naming every tried tool when none exist', function() {
        clearProviders();

        var caught = null;
        try {
            aiChatModule.aiChat('hi');
        } catch (e) {
            caught = e;
        }

        assert.ok(caught, 'must throw when no provider is available');
        PROVIDER_NAMES.forEach(function(name) {
            assert.contains(caught.message, name, 'error lists ' + name);
        });
        clearProviders();
    });

    test('throws the "no provider tools" error when providers exist but all return undefined', function() {
        clearProviders();
        setProvider('gemini_ai_chat', function(message) { return undefined; });
        setProvider('codex_ai', function(message) { return undefined; });

        var caught = null;
        try {
            aiChatModule.aiChat('hi');
        } catch (e) {
            caught = e;
        }

        assert.ok(caught, 'must throw when no provider produced a result');
        assert.contains(caught.message, 'No AI provider tools available', 'pins the current fallback error shape');
        clearProviders();
    });

    test('passes the message through verbatim', function() {
        clearProviders();
        var seen = null;
        setProvider('claude_ai_chat', function(message) { seen = message; return 'ok'; });

        aiChatModule.aiChat('multi\nline\nprompt');

        assert.equal(seen, 'multi\nline\nprompt');
        clearProviders();
    });
});
