 * Unit tests for js/common/aiChat.js — provider-dispatch chat helper.
 *
 * The module resolves AI provider tools from the global scope
 * (globalThis/window) and tries them in priority order. These tests pin the
 * dispatch order, the validation guard, the last-error propagation and the
 * "no provider" failure shape by injecting provider functions onto the real
 * globalThis (the module reads them at call time).
 *
 * Uses: loadModule(), assert, test(), suite()
 */

var aiChatModule = loadModule('js/common/aiChat.js');

var PROVIDER_NAMES = ['claude_ai_chat', 'gemini_ai_chat', 'codex_ai', 'gemini_cli', 'opencode_ai'];

function clearProviders() {
    PROVIDER_NAMES.forEach(function(name) {
        try { delete globalThis[name]; } catch (e) { globalThis[name] = undefined; }
    });
}

function setProvider(name, fn) {
    globalThis[name] = fn;
}

function getProvider(name) {
    return globalThis[name];
}

suite('aiChat.aiChat', function() {
    test('rejects a missing or non-string message', function() {
        assert.throws(function() { aiChatModule.aiChat(null); }, 'null message must throw');
        assert.throws(function() { aiChatModule.aiChat(42); }, 'numeric message must throw');
        assert.throws(function() { aiChatModule.aiChat({}); }, 'object message must throw');
    });

    test('rejects an empty or whitespace-only message', function() {
        assert.throws(function() { aiChatModule.aiChat(''); }, 'empty message must throw');
        assert.throws(function() { aiChatModule.aiChat('   '); }, 'whitespace-only message must throw');
    });

    test('uses the first available provider and returns its result', function() {
        clearProviders();
        var calls = [];
        setProvider('gemini_ai_chat', function(message) { calls.push(['gemini_ai_chat', message]); return 'gemini-result'; });
        setProvider('codex_ai', function(message) { calls.push(['codex_ai', message]); return 'codex-result'; });

        var result = aiChatModule.aiChat('hello');

        assert.equal(result, 'gemini-result');
        assert.deepEqual(calls, [['gemini_ai_chat', 'hello']], 'higher-priority provider wins, later providers are not tried');
        clearProviders();
    });

    test('claude_ai_chat has priority over gemini_ai_chat', function() {
        clearProviders();
        var calls = [];
        setProvider('claude_ai_chat', function(message) { calls.push('claude_ai_chat'); return 'claude-result'; });
        setProvider('gemini_ai_chat', function(message) { calls.push('gemini_ai_chat'); return 'gemini-result'; });

        var result = aiChatModule.aiChat('hi');

        assert.equal(result, 'claude-result');
        assert.deepEqual(calls, ['claude_ai_chat']);
        clearProviders();
    });

    test('falls through to the next provider when an earlier one is absent', function() {
        clearProviders();
        var calls = [];
        setProvider('opencode_ai', function(message) { calls.push('opencode_ai'); return 'opencode-result'; });

        var result = aiChatModule.aiChat('hi');

