     - if none: merge --abort (swallow), warn 'Merge failed (non-conflict reason):', msg, return []
     - else: build file list, warn '⚠️ Merge conflicts in N file(s):', list, build md, file_write merge_conflicts.md, log '✅ Wrote merge_conflicts.md', return conflictFiles
  b. catch statusError: warn 'Could not determine merge state after conflict:', statusError; merge --abort; return []

