        } catch (e) {
            console.warn('Failed to post sticky-approval comment on PR #' + pr.number + ':', e.message || e);
        }
        console.log('ℹ️ Sticky approval on PR #' + pr.number + ' — re-review NOT armed; re-validation + merge follow');
    }
}

