   return {
       'git rev-parse --is-shallow-repository': spec.shallow === 'THROW'
           ? { throw: 'shallow probe failed' }
           : { out: (spec.shallow || 'false') + '\nCOMMAND_EXIT_CODE=0' },
       'git diff --cached --quiet HEAD': spec.quietThrow
           ? { throw: spec.quietThrow }
           : { out: 'COMMAND_EXIT_CODE=0' },
       'git status --short': spec.statusThrow
           ? { throw: spec.statusThrow }
           : { out: (spec.statusRaw || '') + '\nCOMMAND_EXIT_CODE=0' }
   };
}

function makeConflictCmdMock(spec) {
   var table = conflictResponses(spec);
   return function(args) {
       var c = args.command || '';
       if (c.indexOf('git merge origin/') === 0) {
           if (spec.mergeThrow) throw new Error(spec.mergeThrow);
           if (spec.record) spec.record(c, args);
           return 'Merge cleanup\nCOMMAND_EXIT_CODE=0';
